do $$ begin if public.blog_community_schema_version()<>1 then raise exception 'Blog prerequisites missing'; end if; end $$;
with editorial as (select * from jsonb_to_recordset('[{"slug":"styler-hijab-quotidien","title":"Une garde-robe capsule qui vous ressemble vraiment","category":"Style","excerpt":"Moins d’hésitations, davantage de possibilités : une méthode concrète pour composer une sélection de vêtements qui fonctionne au quotidien.","body":"Le meilleur point de départ d’une garde-robe n’est pas une liste de pièces incontournables. C’est votre semaine réelle : déplacements, travail, moments à la maison, sorties et météo. Une garde-robe capsule sert à rendre ces journées plus simples, sans transformer votre style en uniforme.\n\n## Partir des vêtements déjà portés\n\nPendant quelques jours, mettez de côté les pièces que vous choisissez spontanément. Observez leurs points communs : une taille confortable, une longueur pratique, une couleur facile à associer. Ce petit inventaire est plus utile qu’un achat destiné à une vie imaginaire.\n\n## Choisir une palette ouverte\n\nDeux ou trois couleurs de fond permettent de multiplier les associations. Noir et gris, beige et crème, marine et écru : il n’existe pas de bonne palette universelle. Ajoutez une couleur qui vous plaît réellement, puis vérifiez qu’elle se combine avec au moins deux pièces déjà présentes.\n\n## Penser en silhouettes, pas en quantités\n\nPréparez trois associations complètes : une pour une journée active, une pour une journée plus habillée, une pour un moment détendu. Faites varier une seule pièce pour découvrir d’autres possibilités. Une veste sur un ensemble ou un pantalon différent peut suffire à changer l’allure.\n\n## Acheter pour résoudre un besoin précis\n\nAvant d’ajouter un vêtement, demandez-vous ce qu’il permet de porter. Vérifiez la coupe, les mesures disponibles et les consignes d’entretien. Si une information manque, posez la question : une matière ou une taille ne se devine pas sur une photographie.\n\n## Le petit exercice à essayer\n\nPhotographiez cinq tenues que vous aimez avec vos propres vêtements. Gardez ces images à portée de main les matins pressés. La capsule devient alors un outil personnel, évolutif, fait pour être porté plutôt que parfait sur un portant.","image":"/images/journal-capsule.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Une garde-robe capsule qui vous ressemble vraiment","excerpt":"Moins d’hésitations, davantage de possibilités : une méthode concrète pour composer une sélection de vêtements qui fonctionne au quotidien.","body":"Le meilleur point de départ d’une garde-robe n’est pas une liste de pièces incontournables. C’est votre semaine réelle : déplacements, travail, moments à la maison, sorties et météo. Une garde-robe capsule sert à rendre ces journées plus simples, sans transformer votre style en uniforme.\n\n## Partir des vêtements déjà portés\n\nPendant quelques jours, mettez de côté les pièces que vous choisissez spontanément. Observez leurs points communs : une taille confortable, une longueur pratique, une couleur facile à associer. Ce petit inventaire est plus utile qu’un achat destiné à une vie imaginaire.\n\n## Choisir une palette ouverte\n\nDeux ou trois couleurs de fond permettent de multiplier les associations. Noir et gris, beige et crème, marine et écru : il n’existe pas de bonne palette universelle. Ajoutez une couleur qui vous plaît réellement, puis vérifiez qu’elle se combine avec au moins deux pièces déjà présentes.\n\n## Penser en silhouettes, pas en quantités\n\nPréparez trois associations complètes : une pour une journée active, une pour une journée plus habillée, une pour un moment détendu. Faites varier une seule pièce pour découvrir d’autres possibilités. Une veste sur un ensemble ou un pantalon différent peut suffire à changer l’allure.\n\n## Acheter pour résoudre un besoin précis\n\nAvant d’ajouter un vêtement, demandez-vous ce qu’il permet de porter. Vérifiez la coupe, les mesures disponibles et les consignes d’entretien. Si une information manque, posez la question : une matière ou une taille ne se devine pas sur une photographie.\n\n## Le petit exercice à essayer\n\nPhotographiez cinq tenues que vous aimez avec vos propres vêtements. Gardez ces images à portée de main les matins pressés. La capsule devient alors un outil personnel, évolutif, fait pour être porté plutôt que parfait sur un portant."},"en":{"title":"A capsule wardrobe that actually feels like you","excerpt":"A practical way to build an easy-to-wear wardrobe around your real days, preferences and existing clothes.","body":"A useful capsule wardrobe starts with your actual week, not a universal list of essentials. Consider travel, work, quieter days and the weather. The aim is easier decisions, while keeping your personal style.\n\n## Notice what you already wear\n\nSet aside the clothes you reach for naturally. Look for shared features: a comfortable waist, a useful length or colours you enjoy combining. These observations reveal more than a shopping list.\n\n## Build outfits before buying\n\nChoose two or three base colours and one accent you love. Make three complete outfits for different parts of your week. Change one element at a time: a jacket, trousers or shoes can create a new direction without replacing everything.\n\n## Give each purchase a purpose\n\nAsk which existing clothes a new piece will work with. Check the available measurements, fit advice and care label. Do not infer fabric composition or size from a photograph.\n\n## Keep a personal outfit library\n\nPhotograph five combinations you genuinely enjoy wearing. Use them on busy mornings, and adjust your selection as your routine changes. A capsule is a working wardrobe, not a fixed rule."},"ar":{"title":"خزانة صغيرة ومنسقة تعكس ذوقك","excerpt":"خطوات عملية لتنسيق ملابس تناسب أيامك الفعلية وتمنح القطع الموجودة إمكانيات أكثر.","body":"تبدأ الخزانة العملية بنمط حياتك الحقيقي: العمل والتنقل والراحة والطقس. الهدف هو تسهيل الاختيار مع الحفاظ على ذوقك، وليس الالتزام بقائمة ثابتة من القطع.\n\n## ملاحظة ما ترتديه فعلاً\n\nضع جانباً القطع التي تختارها تلقائياً. ما الذي يجمعها؟ خصر مريح أو طول مناسب أو ألوان سهلة التنسيق؟ هذه الملاحظات تساعدك على فهم احتياجاتك.\n\n## تنسيق إطلالات كاملة\n\nاختر لونين أو ثلاثة كأساس وأضف لوناً تحبه. جهّز ثلاثة تنسيقات لأوقات مختلفة من الأسبوع، ثم بدّل قطعة واحدة لاكتشاف خيارات جديدة.\n\n## الشراء لهدف واضح\n\nقبل شراء قطعة، حدّد الملابس الموجودة التي تناسبها. راجع القياسات والمعلومات المتاحة وتعليمات العناية. لا يمكن الجزم بالخامة أو المقاس اعتماداً على الصورة.\n\n## تجربة بسيطة\n\nصوّر خمسة تنسيقات تحب ارتداءها وارجع إليها عندما يضيق الوقت. تتطور الخزانة مع يومك واحتياجاتك، ولا تحتاج إلى أن تكون مثالية."}}},{"slug":"art-abaya-moderne","title":"L’art des superpositions : du relief, sans compliquer la tenue","category":"Silhouettes","excerpt":"Jouer avec les longueurs, les volumes et les textures pour composer une silhouette lisible et agréable à porter.","body":"Superposer n’oblige pas à accumuler. Une base simple et une pièce extérieure bien choisie créent déjà du relief. L’intérêt se trouve souvent dans la façon dont un col, une manche ou un ourlet répond à une autre ligne.\n\n## Commencer par une base confortable\n\nEssayez d’abord le haut et le bas sans veste. Vérifiez que vous pouvez vous asseoir et marcher aisément. La pièce extérieure doit enrichir une tenue qui fonctionne déjà, plutôt que corriger un inconfort.\n\n## Donner un rôle à chaque longueur\n\nUn haut plus court avec un pantalon ample produit une lecture différente d’une pièce longue laissée ouverte. Regardez la silhouette dans son ensemble, puis choisissez la ligne que vous souhaitez mettre en valeur. Il n’existe pas de proportion obligatoire.\n\n## Équilibrer les volumes selon vos envies\n\nSi les manches et le pantalon sont amples, une ligne de col nette ou une ouverture verticale peut structurer l’ensemble. À l’inverse, une base sobre accueille facilement une veste plus expressive. Ce sont des pistes d’essayage, pas des règles liées à une morphologie.\n\n## Laisser dialoguer les textures\n\nUne surface lisse près d’une maille visuellement plus présente apporte du contraste. Limitez les éléments qui attirent simultanément le regard si vous recherchez un résultat calme. Pour un effet plus affirmé, rapprochez deux textures, puis gardez les accessoires simples.\n\n## Vérifier la tenue en mouvement\n\nLevez les bras, asseyez-vous, fermez la veste et essayez votre sac. Les épaisseurs doivent rester compatibles avec vos gestes et la température. Une photographie immobile ne dit pas tout du confort.\n\n## Une formule facile à réinterpréter\n\nPartez d’un pantalon que vous portez souvent, ajoutez un haut uni et essayez deux pièces extérieures de longueurs différentes. Gardez celle qui vous donne envie de bouger et de sortir : la bonne superposition reste celle que vous aurez plaisir à porter.","image":"/images/journal-superpositions.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"L’art des superpositions : du relief, sans compliquer la tenue","excerpt":"Jouer avec les longueurs, les volumes et les textures pour composer une silhouette lisible et agréable à porter.","body":"Superposer n’oblige pas à accumuler. Une base simple et une pièce extérieure bien choisie créent déjà du relief. L’intérêt se trouve souvent dans la façon dont un col, une manche ou un ourlet répond à une autre ligne.\n\n## Commencer par une base confortable\n\nEssayez d’abord le haut et le bas sans veste. Vérifiez que vous pouvez vous asseoir et marcher aisément. La pièce extérieure doit enrichir une tenue qui fonctionne déjà, plutôt que corriger un inconfort.\n\n## Donner un rôle à chaque longueur\n\nUn haut plus court avec un pantalon ample produit une lecture différente d’une pièce longue laissée ouverte. Regardez la silhouette dans son ensemble, puis choisissez la ligne que vous souhaitez mettre en valeur. Il n’existe pas de proportion obligatoire.\n\n## Équilibrer les volumes selon vos envies\n\nSi les manches et le pantalon sont amples, une ligne de col nette ou une ouverture verticale peut structurer l’ensemble. À l’inverse, une base sobre accueille facilement une veste plus expressive. Ce sont des pistes d’essayage, pas des règles liées à une morphologie.\n\n## Laisser dialoguer les textures\n\nUne surface lisse près d’une maille visuellement plus présente apporte du contraste. Limitez les éléments qui attirent simultanément le regard si vous recherchez un résultat calme. Pour un effet plus affirmé, rapprochez deux textures, puis gardez les accessoires simples.\n\n## Vérifier la tenue en mouvement\n\nLevez les bras, asseyez-vous, fermez la veste et essayez votre sac. Les épaisseurs doivent rester compatibles avec vos gestes et la température. Une photographie immobile ne dit pas tout du confort.\n\n## Une formule facile à réinterpréter\n\nPartez d’un pantalon que vous portez souvent, ajoutez un haut uni et essayez deux pièces extérieures de longueurs différentes. Gardez celle qui vous donne envie de bouger et de sortir : la bonne superposition reste celle que vous aurez plaisir à porter."},"en":{"title":"Thoughtful layering, without overcomplicating an outfit","excerpt":"Use lengths, volume and texture to create depth while keeping comfort and clarity.","body":"Layering can start with just a comfortable base and one outer piece. A collar, sleeve or hem can add interest without adding many garments.\n\n## Let the base work first\n\nTry the top and bottoms without a jacket. Sit, walk and move your arms. The outer layer should enrich an outfit that already feels good.\n\n## Explore lengths and volumes\n\nA short top with wide trousers creates a different line from a long open jacket. Neither is a universal ideal. Try both and notice the silhouette you prefer. A clean neckline or vertical opening can bring definition to generous shapes.\n\n## Combine texture deliberately\n\nA smooth surface next to a more prominent knit creates contrast. If you want a calm result, limit competing details. For a stronger effect, combine textures and keep accessories simple.\n\n## Make movement part of the fitting\n\nClose the jacket, carry your bag and sit down. Check that the layers suit both the temperature and your daily gestures. The most successful combination is one you enjoy wearing, not simply photographing."},"ar":{"title":"تنسيق الطبقات ببساطة وراحة","excerpt":"أفكار لتجربة الأطوال والأحجام والملمس دون تعقيد الإطلالة.","body":"لا يتطلب تنسيق الطبقات كثرة القطع. قد يكفي أساس مريح وسترة مناسبة لإضافة عمق من خلال الياقة أو الأكمام أو اختلاف الأطوال.\n\n## البداية من أساس مريح\n\nجرّب القطعة العلوية والبنطال من دون سترة، ثم اجلس وامشِ وارفع ذراعيك. يفترض أن تضيف الطبقة الخارجية شيئاً إلى تنسيق مريح أصلاً.\n\n## تجربة الأطوال والأحجام\n\nيختلف أثر القطعة القصيرة مع البنطال الواسع عن السترة الطويلة المفتوحة. لا توجد نسبة مثالية للجميع. جرّب ما يوافق ذوقك، واستعن بخط ياقة واضح أو فتحة عمودية إذا رغبت في تحديد الشكل.\n\n## الاهتمام بالملمس والحركة\n\nيمكن لسطح ناعم بجانب نسيج أكثر بروزاً أن يصنع تبايناً هادئاً. احمل حقيبتك وأغلق السترة وتأكد من مناسبة الطبقات لدرجة الحرارة وحركتك اليومية."}}},{"slug":"guide-tenues-priere","title":"Bien choisir une coupe : les détails qui changent le confort","category":"Bien choisir","excerpt":"Mesures, aisance, longueur et mouvement : les bons réflexes pour choisir une pièce à distance avec plus de confiance.","body":"Une coupe confortable se reconnaît dans les gestes ordinaires. Marcher, s’asseoir ou tendre les bras révèle parfois ce qu’un miroir ne montre pas. Lors d’un achat en ligne, quelques vérifications concrètes aident à se projeter sans promettre un résultat universel.\n\n## Comparer avec une pièce connue\n\nPrenez un vêtement dans lequel vous êtes à l’aise, posez-le à plat et mesurez les dimensions utiles. Comparez uniquement des mesures prises de la même façon. Un tour du corps et une largeur de vêtement à plat ne sont pas interchangeables.\n\n## Lire « taille unique » avec précision\n\nCette mention décrit une proposition de taille, pas la garantie qu’une pièce conviendra à tout le monde. Consultez la plage conseillée lorsqu’elle est renseignée, les mesures vérifiées et le type de coupe. Demandez une précision si vous hésitez.\n\n## Repérer où se trouve l’aisance\n\nSur un haut, regardez les épaules, l’ouverture des manches et la longueur. Sur un pantalon, intéressez-vous à la taille, à la hauteur de fourche et à la jambe. Un volume ample peut être agréable, mais il doit rester compatible avec vos usages.\n\n## Distinguer l’apparence et la composition\n\nUne maille qui semble épaisse ou un tissu qui paraît fluide ne permet pas de connaître sa composition exacte. Fiez-vous aux informations confirmées sur la fiche ou à l’étiquette du vêtement. Le confort thermique dépend aussi de votre environnement et des autres couches portées.\n\n## Faire un essayage utile\n\nÀ réception, essayez la pièce avec les chaussures et sous-couches prévues, en respectant les conditions d’essayage et de retour. Testez plusieurs mouvements et prenez le temps d’observer les points de tension.\n\n## La question à poser avant de commander\n\nRemplacez « est-ce que cela taille bien ? » par une question précise : quelle est la longueur, la largeur à plat, ou la mesure de taille disponible ? Une réponse factuelle aide davantage qu’une appréciation générale.","image":"/images/journal-confort.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Bien choisir une coupe : les détails qui changent le confort","excerpt":"Mesures, aisance, longueur et mouvement : les bons réflexes pour choisir une pièce à distance avec plus de confiance.","body":"Une coupe confortable se reconnaît dans les gestes ordinaires. Marcher, s’asseoir ou tendre les bras révèle parfois ce qu’un miroir ne montre pas. Lors d’un achat en ligne, quelques vérifications concrètes aident à se projeter sans promettre un résultat universel.\n\n## Comparer avec une pièce connue\n\nPrenez un vêtement dans lequel vous êtes à l’aise, posez-le à plat et mesurez les dimensions utiles. Comparez uniquement des mesures prises de la même façon. Un tour du corps et une largeur de vêtement à plat ne sont pas interchangeables.\n\n## Lire « taille unique » avec précision\n\nCette mention décrit une proposition de taille, pas la garantie qu’une pièce conviendra à tout le monde. Consultez la plage conseillée lorsqu’elle est renseignée, les mesures vérifiées et le type de coupe. Demandez une précision si vous hésitez.\n\n## Repérer où se trouve l’aisance\n\nSur un haut, regardez les épaules, l’ouverture des manches et la longueur. Sur un pantalon, intéressez-vous à la taille, à la hauteur de fourche et à la jambe. Un volume ample peut être agréable, mais il doit rester compatible avec vos usages.\n\n## Distinguer l’apparence et la composition\n\nUne maille qui semble épaisse ou un tissu qui paraît fluide ne permet pas de connaître sa composition exacte. Fiez-vous aux informations confirmées sur la fiche ou à l’étiquette du vêtement. Le confort thermique dépend aussi de votre environnement et des autres couches portées.\n\n## Faire un essayage utile\n\nÀ réception, essayez la pièce avec les chaussures et sous-couches prévues, en respectant les conditions d’essayage et de retour. Testez plusieurs mouvements et prenez le temps d’observer les points de tension.\n\n## La question à poser avant de commander\n\nRemplacez « est-ce que cela taille bien ? » par une question précise : quelle est la longueur, la largeur à plat, ou la mesure de taille disponible ? Une réponse factuelle aide davantage qu’une appréciation générale."},"en":{"title":"Choosing a fit: small details that make a difference","excerpt":"Measurements, ease and movement: practical checks for choosing clothes online with more confidence.","body":"Comfort shows itself when you walk, sit or reach. When buying online, start with a garment you know and enjoy wearing.\n\n## Compare like-for-like measurements\n\nLay your reference garment flat and measure the relevant areas. Only compare measurements taken in the same way: body circumference and a flat garment width are different things.\n\n## Read one-size information carefully\n\nOne size is not a promise of universal fit. Check any confirmed measurements, recommended range and fit advice. Ask for a specific dimension when information is missing.\n\n## Look at ease and length\n\nFor tops, consider shoulders, sleeves and length. For trousers, consider the waist, rise and leg. A generous cut should still suit your movements and daily routine.\n\n## Separate appearance from confirmed facts\n\nA photograph cannot establish fabric composition or warmth. Use the product information and care label. On arrival, try the garment with your intended layers and shoes, respecting the fitting and return conditions."},"ar":{"title":"اختيار القصة: تفاصيل تصنع الفرق في الراحة","excerpt":"القياسات وسهولة الحركة والطول: خطوات عملية عند شراء الملابس عبر الإنترنت.","body":"تظهر الراحة عند المشي والجلوس ومد الذراعين. يمكن الاستعانة بقطعة تملكها وتشعر فيها بالراحة قبل اختيار قطعة جديدة.\n\n## مقارنة القياسات بالطريقة نفسها\n\nضع القطعة على سطح مستوٍ وقس الأبعاد المهمة. لا تقارن محيط الجسم بعرض القطعة وهي مفرودة، فهما قياسان مختلفان.\n\n## فهم المقاس الواحد\n\nعبارة المقاس الواحد لا تعني ملاءمة الجميع. راجع المدى الموصى به والقياسات المؤكدة ونصائح القصة، واطلب معلومة محددة إذا كانت ناقصة.\n\n## مراعاة الحركة والخامة\n\nانتبه إلى الكتفين والأكمام والطول في القطع العلوية، وإلى الخصر وارتفاعه والساق في البناطيل. لا تكفي الصورة لتحديد تركيب الخامة أو دفئها. جرّب القطعة عند الاستلام وفق شروط التجربة والإرجاع."}}},{"slug":"mode-modeste-2026","title":"Associer les couleurs sans suivre de règles rigides","category":"Couleurs","excerpt":"Une base, une couleur d’accent et quelques essais : construire une palette personnelle devient plus simple.","body":"Associer les couleurs n’est pas un examen à réussir. Il s’agit de trouver des rapprochements qui vous plaisent et qui fonctionnent avec vos vêtements. La lumière, la texture et les proportions influencent autant le résultat que le nom d’une teinte.\n\n## Choisir l’atmosphère avant la palette\n\nSouhaitez-vous une tenue discrète, lumineuse ou plus contrastée ? Cette intention aide à choisir. Un camaïeu peut donner une impression calme ; une couleur d’accent peut devenir le point de départ d’un ensemble plus expressif.\n\n## Tester une couleur en petite proportion\n\nSi une teinte vous attire sans vous sembler facile, commencez par une seule pièce. Essayez-la avec deux bases différentes. Photographiez les associations en lumière naturelle : cela aide à comparer sans multiplier les achats.\n\n## Donner de la profondeur aux neutres\n\nDes nuances proches ne sont pas nécessairement identiques. Crème, beige et taupe peuvent dialoguer, mais leur sous-ton et leur texture modifient l’équilibre. Posez les pièces côte à côte plutôt que de vous fier aux noms affichés à l’écran.\n\n## Garder un point de repère\n\nDans une association très colorée, répéter discrètement une teinte dans une autre partie de la tenue peut créer un lien. Si vous préférez des contrastes francs, laissez-les exister : l’harmonie ne signifie pas tout assortir.\n\n## Comprendre la limite des photos\n\nL’écran, l’éclairage de la prise de vue et les réglages de l’appareil influencent la couleur perçue. Les pastilles sont des repères de sélection, pas des mesures du tissu. Vérifiez les photos associées au coloris ; une vue générale ne confirme pas une teinte particulière.\n\n## Un exercice pour trouver votre palette\n\nChoisissez une couleur que vous aimez déjà et composez trois versions : avec une base claire, une base foncée et une nuance proche. Gardez les associations dans lesquelles vous vous sentez le mieux, sans chercher une validation extérieure.","image":"/images/journal-couleurs.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Associer les couleurs sans suivre de règles rigides","excerpt":"Une base, une couleur d’accent et quelques essais : construire une palette personnelle devient plus simple.","body":"Associer les couleurs n’est pas un examen à réussir. Il s’agit de trouver des rapprochements qui vous plaisent et qui fonctionnent avec vos vêtements. La lumière, la texture et les proportions influencent autant le résultat que le nom d’une teinte.\n\n## Choisir l’atmosphère avant la palette\n\nSouhaitez-vous une tenue discrète, lumineuse ou plus contrastée ? Cette intention aide à choisir. Un camaïeu peut donner une impression calme ; une couleur d’accent peut devenir le point de départ d’un ensemble plus expressif.\n\n## Tester une couleur en petite proportion\n\nSi une teinte vous attire sans vous sembler facile, commencez par une seule pièce. Essayez-la avec deux bases différentes. Photographiez les associations en lumière naturelle : cela aide à comparer sans multiplier les achats.\n\n## Donner de la profondeur aux neutres\n\nDes nuances proches ne sont pas nécessairement identiques. Crème, beige et taupe peuvent dialoguer, mais leur sous-ton et leur texture modifient l’équilibre. Posez les pièces côte à côte plutôt que de vous fier aux noms affichés à l’écran.\n\n## Garder un point de repère\n\nDans une association très colorée, répéter discrètement une teinte dans une autre partie de la tenue peut créer un lien. Si vous préférez des contrastes francs, laissez-les exister : l’harmonie ne signifie pas tout assortir.\n\n## Comprendre la limite des photos\n\nL’écran, l’éclairage de la prise de vue et les réglages de l’appareil influencent la couleur perçue. Les pastilles sont des repères de sélection, pas des mesures du tissu. Vérifiez les photos associées au coloris ; une vue générale ne confirme pas une teinte particulière.\n\n## Un exercice pour trouver votre palette\n\nChoisissez une couleur que vous aimez déjà et composez trois versions : avec une base claire, une base foncée et une nuance proche. Gardez les associations dans lesquelles vous vous sentez le mieux, sans chercher une validation extérieure."},"en":{"title":"Combining colours without rigid rules","excerpt":"Build a personal palette through a base, an accent and a few useful experiments.","body":"Colour combinations are a matter of preference, not a test. Light, texture and proportion all change the way an outfit feels.\n\n## Start with an intention\n\nDo you want a quiet, bright or contrasting outfit? Related shades can feel calm, while an accent creates a focal point. Try one new colour with two bases you already own.\n\n## Give neutrals some depth\n\nCream, beige and taupe are not interchangeable. Place garments side by side to compare undertones and textures instead of relying only on colour names.\n\n## Use photographs thoughtfully\n\nScreens and lighting affect colour perception. Swatches are selection aids, not fabric measurements. Check photographs actually assigned to your chosen colour; a general view does not confirm a specific shade.\n\n## Try three combinations\n\nChoose a colour you already enjoy. Wear it with a light base, a dark base and a neighbouring shade. Keep the versions that feel right to you."},"ar":{"title":"تنسيق الألوان بعيداً عن القواعد الجامدة","excerpt":"لون أساسي ولمسة مميزة وتجارب بسيطة لبناء لوحة ألوان شخصية.","body":"تنسيق الألوان مسألة ذوق وتجربة. تؤثر الإضاءة والخامة ونسبة كل لون في النتيجة النهائية.\n\n## تحديد الإحساس المطلوب\n\nهل ترغب في تنسيق هادئ أم مشرق أم واضح التباين؟ جرّب لوناً واحداً جديداً مع أساسين موجودين في خزانتك.\n\n## مقارنة الدرجات المتقاربة\n\nالكريمي والبيج والتاوب ليست درجات متطابقة. ضع القطع جنباً إلى جنب لملاحظة اختلاف الدرجة والملمس، بدلاً من الاكتفاء بالاسم.\n\n## الانتباه إلى الصور\n\nتؤثر الشاشة وإضاءة التصوير في اللون الظاهر. دوائر الألوان أدوات للاختيار وليست قياسات للخامة. راجع الصور المرتبطة باللون المحدد؛ فالصورة العامة لا تؤكد درجة بعينها.\n\n## تجربة ثلاث مجموعات\n\nنسّق لوناً تحبه مع أساس فاتح وآخر داكن ودرجة قريبة. احتفظ بما يناسب ذوقك وراحتك."}}},{"slug":"entretien-hijabs-soie","title":"Laver, sécher, ranger : les réflexes d’une garde-robe soignée","category":"Entretien","excerpt":"Des gestes mesurés et une attention à l’étiquette, plutôt qu’une méthode unique appliquée à tous les vêtements.","body":"Prendre soin d’un vêtement commence avant le lavage. Observer une petite tache, aérer une pièce lorsque cela convient et ranger sans comprimer sont déjà des gestes utiles. L’objectif est de respecter le vêtement, sans lui appliquer une recette universelle.\n\n## L’étiquette reste le premier repère\n\nVérifiez les symboles et les instructions du fabricant. Une maille, une doublure et un accessoire peuvent imposer des précautions différentes, même si l’ensemble semble simple. Si la consigne est absente ou ambiguë, demandez conseil avant d’utiliser un procédé agressif.\n\n## Préparer le lavage\n\nVidez les poches, vérifiez les fermetures et séparez les textiles selon les indications pertinentes. Une couleur foncée ou un tissu visuellement délicat n’indique pas à lui seul le bon programme. Utilisez la température et le traitement autorisés pour la pièce concernée.\n\n## Traiter une tache avec prudence\n\nÉvitez de frotter vigoureusement ou d’appliquer un produit au hasard. Un essai sur une zone discrète ne remplace pas les consignes, mais peut aider à repérer une réaction indésirable lorsque le traitement est autorisé. Pour une pièce délicate ou une tache difficile, un professionnel peut être préférable.\n\n## Respecter la forme pendant le séchage\n\nLe sèche-linge, le séchage suspendu ou à plat ne conviennent pas indistinctement à toutes les pièces. Suivez l’étiquette et disposez le vêtement sans déformer les zones fragiles. La chaleur et l’essorage doivent eux aussi correspondre aux instructions.\n\n## Ranger pour retrouver facilement\n\nLaissez suffisamment d’espace entre les pièces et choisissez le pliage ou le cintre adapté à leur tenue. Rangez des vêtements propres et complètement secs. Réparez un bouton desserré avant qu’il ne se perde : ce petit geste évite parfois une mise de côté durable.\n\n## Un entretien ajusté à la pièce\n\nGardez une photo des étiquettes difficiles à lire. Lors d’un prochain achat, consultez les informations d’entretien disponibles et demandez ce qui manque. Connaître les contraintes d’une pièce aide à choisir un vêtement compatible avec votre quotidien.","image":"/images/journal-entretien.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Laver, sécher, ranger : les réflexes d’une garde-robe soignée","excerpt":"Des gestes mesurés et une attention à l’étiquette, plutôt qu’une méthode unique appliquée à tous les vêtements.","body":"Prendre soin d’un vêtement commence avant le lavage. Observer une petite tache, aérer une pièce lorsque cela convient et ranger sans comprimer sont déjà des gestes utiles. L’objectif est de respecter le vêtement, sans lui appliquer une recette universelle.\n\n## L’étiquette reste le premier repère\n\nVérifiez les symboles et les instructions du fabricant. Une maille, une doublure et un accessoire peuvent imposer des précautions différentes, même si l’ensemble semble simple. Si la consigne est absente ou ambiguë, demandez conseil avant d’utiliser un procédé agressif.\n\n## Préparer le lavage\n\nVidez les poches, vérifiez les fermetures et séparez les textiles selon les indications pertinentes. Une couleur foncée ou un tissu visuellement délicat n’indique pas à lui seul le bon programme. Utilisez la température et le traitement autorisés pour la pièce concernée.\n\n## Traiter une tache avec prudence\n\nÉvitez de frotter vigoureusement ou d’appliquer un produit au hasard. Un essai sur une zone discrète ne remplace pas les consignes, mais peut aider à repérer une réaction indésirable lorsque le traitement est autorisé. Pour une pièce délicate ou une tache difficile, un professionnel peut être préférable.\n\n## Respecter la forme pendant le séchage\n\nLe sèche-linge, le séchage suspendu ou à plat ne conviennent pas indistinctement à toutes les pièces. Suivez l’étiquette et disposez le vêtement sans déformer les zones fragiles. La chaleur et l’essorage doivent eux aussi correspondre aux instructions.\n\n## Ranger pour retrouver facilement\n\nLaissez suffisamment d’espace entre les pièces et choisissez le pliage ou le cintre adapté à leur tenue. Rangez des vêtements propres et complètement secs. Réparez un bouton desserré avant qu’il ne se perde : ce petit geste évite parfois une mise de côté durable.\n\n## Un entretien ajusté à la pièce\n\nGardez une photo des étiquettes difficiles à lire. Lors d’un prochain achat, consultez les informations d’entretien disponibles et demandez ce qui manque. Connaître les contraintes d’une pièce aide à choisir un vêtement compatible avec votre quotidien."},"en":{"title":"Wash, dry, store: thoughtful care for everyday clothes","excerpt":"Start with the care label and adapt your routine to the garment, rather than following one universal method.","body":"Garment care begins before washing. Look at the item, check the care label and avoid treating every fabric in the same way.\n\n## Read the actual instructions\n\nLinings, trims and different materials can require different precautions. Follow the manufacturer’s symbols. If information is missing, ask before using an aggressive treatment.\n\n## Prepare and treat carefully\n\nEmpty pockets and check fastenings. Sort clothes according to the relevant instructions, not appearance alone. Do not scrub a stain vigorously or apply an unfamiliar product at random. A professional may be the better choice for a delicate garment or difficult mark.\n\n## Dry without distorting\n\nTumble drying, hanging and flat drying are not universally suitable. Use the method allowed for that garment and avoid stretching vulnerable areas. Heat and spin settings should also follow the label.\n\n## Store with room to breathe\n\nPut away clean, completely dry garments using suitable hangers or folds. Repair loose buttons promptly. Keep a photograph of hard-to-read labels and consider care requirements before your next purchase."},"ar":{"title":"الغسل والتجفيف والترتيب: عناية مدروسة بالملابس","excerpt":"ابدأ ببطاقة العناية وكيّف خطواتك مع كل قطعة بدلاً من اتباع طريقة واحدة للجميع.","body":"تبدأ العناية بملاحظة القطعة وقراءة تعليماتها. قد تفرض البطانة والزينة والخامات المختلفة احتياطات خاصة.\n\n## بطاقة العناية أولاً\n\nاتبع رموز وتعليمات المصنّع. عند غياب المعلومة، اسأل قبل استخدام معالجة قوية أو حرارة غير مناسبة.\n\n## التحضير ومعالجة البقع\n\nأفرغ الجيوب وافحص السحابات والأزرار. لا تفرك البقعة بقوة أو تستخدم منتجاً عشوائياً. قد تكون الاستعانة بمتخصص أنسب للقطع الحساسة أو البقع الصعبة.\n\n## الحفاظ على الشكل\n\nلا يناسب التجفيف الآلي أو التعليق أو التجفيف المسطح جميع القطع. التزم بالطريقة والحرارة المسموح بهما، وتجنب شد المناطق الضعيفة.\n\n## ترتيب الملابس الجافة\n\nاختر علاقة أو طريقة طي مناسبة، واترك مساحة كافية. أصلح الزر المرتخي واحتفظ بصورة للتعليمات التي يصعب قراءتها."}}},{"slug":"idees-tenues-aid","title":"Du quotidien à une occasion : faire évoluer une tenue en trois gestes","category":"Inspirations","excerpt":"Une même base, plusieurs ambiances : changer le rythme d’un ensemble avec une pièce extérieure, des chaussures et quelques détails.","body":"Une occasion ne demande pas forcément une nouvelle tenue complète. Une base que vous connaissez bien peut prendre une autre direction avec quelques changements choisis. Le confort déjà éprouvé devient un allié, surtout lorsque la journée se prolonge.\n\n## Premier geste : changer la pièce extérieure\n\nUne veste plus structurée, une pièce longue ouverte ou une superposition plus légère modifie la ligne d’ensemble. Essayez la tenue fermée et ouverte. Choisissez selon le lieu et la température plutôt que selon une idée abstraite de ce qui ferait « habillé ».\n\n## Deuxième geste : adapter les chaussures\n\nLes chaussures changent la posture visuelle autant que la façon de se déplacer. Pensez à la durée debout, au trajet et au type de sol. Il n’est pas nécessaire de choisir des talons pour composer une tenue soignée : une paire confortable et adaptée à l’ensemble peut très bien remplir ce rôle.\n\n## Troisième geste : sélectionner un détail\n\nUn sac, une ceinture si la coupe le permet, ou un accessoire peut devenir le point d’attention. Évitez d’ajouter des éléments uniquement parce que l’occasion semble le demander. Un détail que vous aimez suffit souvent à personnaliser une base sobre.\n\n## Prévoir les aspects pratiques\n\nVérifiez les poches, la facilité à porter votre sac et les variations de température. Si vous transportez une seconde paire de chaussures ou une couche supplémentaire, préparez-les avec la tenue. Une bonne organisation évite les changements précipités.\n\n## Faire un essai avant le jour prévu\n\nEssayez l’ensemble quelques minutes en mouvement. Une longueur qui fonctionne avec une paire de chaussures peut être moins pratique avec une autre. Regardez aussi le rendu à la lumière du jour, sans chercher une image parfaite.\n\n## Garder votre propre définition de l’élégance\n\nUne tenue réussie correspond au moment, mais aussi à la personne qui la porte. Réutiliser des pièces et les associer autrement est une démarche créative : vous construisez davantage de possibilités à partir de ce que vous aimez déjà.","image":"/images/journal-occasions.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Du quotidien à une occasion : faire évoluer une tenue en trois gestes","excerpt":"Une même base, plusieurs ambiances : changer le rythme d’un ensemble avec une pièce extérieure, des chaussures et quelques détails.","body":"Une occasion ne demande pas forcément une nouvelle tenue complète. Une base que vous connaissez bien peut prendre une autre direction avec quelques changements choisis. Le confort déjà éprouvé devient un allié, surtout lorsque la journée se prolonge.\n\n## Premier geste : changer la pièce extérieure\n\nUne veste plus structurée, une pièce longue ouverte ou une superposition plus légère modifie la ligne d’ensemble. Essayez la tenue fermée et ouverte. Choisissez selon le lieu et la température plutôt que selon une idée abstraite de ce qui ferait « habillé ».\n\n## Deuxième geste : adapter les chaussures\n\nLes chaussures changent la posture visuelle autant que la façon de se déplacer. Pensez à la durée debout, au trajet et au type de sol. Il n’est pas nécessaire de choisir des talons pour composer une tenue soignée : une paire confortable et adaptée à l’ensemble peut très bien remplir ce rôle.\n\n## Troisième geste : sélectionner un détail\n\nUn sac, une ceinture si la coupe le permet, ou un accessoire peut devenir le point d’attention. Évitez d’ajouter des éléments uniquement parce que l’occasion semble le demander. Un détail que vous aimez suffit souvent à personnaliser une base sobre.\n\n## Prévoir les aspects pratiques\n\nVérifiez les poches, la facilité à porter votre sac et les variations de température. Si vous transportez une seconde paire de chaussures ou une couche supplémentaire, préparez-les avec la tenue. Une bonne organisation évite les changements précipités.\n\n## Faire un essai avant le jour prévu\n\nEssayez l’ensemble quelques minutes en mouvement. Une longueur qui fonctionne avec une paire de chaussures peut être moins pratique avec une autre. Regardez aussi le rendu à la lumière du jour, sans chercher une image parfaite.\n\n## Garder votre propre définition de l’élégance\n\nUne tenue réussie correspond au moment, mais aussi à la personne qui la porte. Réutiliser des pièces et les associer autrement est une démarche créative : vous construisez davantage de possibilités à partir de ce que vous aimez déjà."},"en":{"title":"Everyday to occasion: three thoughtful outfit changes","excerpt":"Give a familiar outfit a different mood through an outer layer, shoes and one personal detail.","body":"An occasion does not always need an entirely new outfit. Start with a base you already feel comfortable wearing and make a few deliberate changes.\n\n## Change the outer layer\n\nA structured jacket, a long open piece or a lighter layer changes the overall line. Try it open and closed, and consider the setting and temperature.\n\n## Choose shoes for the whole event\n\nThink about travel, time spent standing and the surface underfoot. Heels are not a requirement for a polished outfit. Comfortable shoes that work with the clothes can be just as considered.\n\n## Select one personal detail\n\nA bag, a suitable belt or an accessory can create a focal point. You do not need to add things simply because the occasion feels formal.\n\n## Rehearse the practical details\n\nTry the complete outfit in movement, including your bag and shoes. Check lengths and prepare an extra layer if needed. Reinterpreting familiar pieces is a creative way to discover more possibilities in the clothes you already enjoy."},"ar":{"title":"من اليوم العادي إلى المناسبة بثلاث لمسات","excerpt":"تغيير طابع تنسيق مألوف من خلال طبقة خارجية وحذاء وتفصيل شخصي.","body":"لا تتطلب المناسبة شراء إطلالة كاملة. ابدأ بملابس تعرف راحتها وأضف تغييرات محددة تناسب المكان والوقت.\n\n## تغيير الطبقة الخارجية\n\nتغيّر سترة محددة القصة أو قطعة طويلة مفتوحة خط الإطلالة. جرّبها مفتوحة ومغلقة وراعِ الطقس.\n\n## اختيار حذاء مناسب\n\nفكّر في التنقل ومدة الوقوف والأرضية. لا يشترط الكعب للحصول على تنسيق أنيق؛ فالحذاء المريح المتناسق قد يؤدي الدور نفسه.\n\n## إضافة تفصيل تحبه\n\nقد تصنع حقيبة أو حزام مناسب للقصة أو إكسسوار نقطة اهتمام. لا تضف تفاصيل لمجرد أن المناسبة تبدو رسمية.\n\n## تجربة التنسيق كاملاً\n\nامشِ واجلس واحمل حقيبتك وتحقق من الأطوال. إن إعادة تنسيق القطع المألوفة تمنح خزانتك خيارات جديدة وتحافظ على أسلوبك الشخصي."}}}]'::jsonb) as x(slug text,title text,category text,excerpt text,body text,image text,author text,read_minutes integer,translations jsonb))
insert into public.blog_editorial_backups(post_id,revision,snapshot)
select p.id,'journal-refresh-v1',to_jsonb(p) from public.blog_posts p join editorial e on e.slug=p.slug
on conflict(post_id,revision) do nothing;
with editorial as (select * from jsonb_to_recordset('[{"slug":"styler-hijab-quotidien","title":"Une garde-robe capsule qui vous ressemble vraiment","category":"Style","excerpt":"Moins d’hésitations, davantage de possibilités : une méthode concrète pour composer une sélection de vêtements qui fonctionne au quotidien.","body":"Le meilleur point de départ d’une garde-robe n’est pas une liste de pièces incontournables. C’est votre semaine réelle : déplacements, travail, moments à la maison, sorties et météo. Une garde-robe capsule sert à rendre ces journées plus simples, sans transformer votre style en uniforme.\n\n## Partir des vêtements déjà portés\n\nPendant quelques jours, mettez de côté les pièces que vous choisissez spontanément. Observez leurs points communs : une taille confortable, une longueur pratique, une couleur facile à associer. Ce petit inventaire est plus utile qu’un achat destiné à une vie imaginaire.\n\n## Choisir une palette ouverte\n\nDeux ou trois couleurs de fond permettent de multiplier les associations. Noir et gris, beige et crème, marine et écru : il n’existe pas de bonne palette universelle. Ajoutez une couleur qui vous plaît réellement, puis vérifiez qu’elle se combine avec au moins deux pièces déjà présentes.\n\n## Penser en silhouettes, pas en quantités\n\nPréparez trois associations complètes : une pour une journée active, une pour une journée plus habillée, une pour un moment détendu. Faites varier une seule pièce pour découvrir d’autres possibilités. Une veste sur un ensemble ou un pantalon différent peut suffire à changer l’allure.\n\n## Acheter pour résoudre un besoin précis\n\nAvant d’ajouter un vêtement, demandez-vous ce qu’il permet de porter. Vérifiez la coupe, les mesures disponibles et les consignes d’entretien. Si une information manque, posez la question : une matière ou une taille ne se devine pas sur une photographie.\n\n## Le petit exercice à essayer\n\nPhotographiez cinq tenues que vous aimez avec vos propres vêtements. Gardez ces images à portée de main les matins pressés. La capsule devient alors un outil personnel, évolutif, fait pour être porté plutôt que parfait sur un portant.","image":"/images/journal-capsule.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Une garde-robe capsule qui vous ressemble vraiment","excerpt":"Moins d’hésitations, davantage de possibilités : une méthode concrète pour composer une sélection de vêtements qui fonctionne au quotidien.","body":"Le meilleur point de départ d’une garde-robe n’est pas une liste de pièces incontournables. C’est votre semaine réelle : déplacements, travail, moments à la maison, sorties et météo. Une garde-robe capsule sert à rendre ces journées plus simples, sans transformer votre style en uniforme.\n\n## Partir des vêtements déjà portés\n\nPendant quelques jours, mettez de côté les pièces que vous choisissez spontanément. Observez leurs points communs : une taille confortable, une longueur pratique, une couleur facile à associer. Ce petit inventaire est plus utile qu’un achat destiné à une vie imaginaire.\n\n## Choisir une palette ouverte\n\nDeux ou trois couleurs de fond permettent de multiplier les associations. Noir et gris, beige et crème, marine et écru : il n’existe pas de bonne palette universelle. Ajoutez une couleur qui vous plaît réellement, puis vérifiez qu’elle se combine avec au moins deux pièces déjà présentes.\n\n## Penser en silhouettes, pas en quantités\n\nPréparez trois associations complètes : une pour une journée active, une pour une journée plus habillée, une pour un moment détendu. Faites varier une seule pièce pour découvrir d’autres possibilités. Une veste sur un ensemble ou un pantalon différent peut suffire à changer l’allure.\n\n## Acheter pour résoudre un besoin précis\n\nAvant d’ajouter un vêtement, demandez-vous ce qu’il permet de porter. Vérifiez la coupe, les mesures disponibles et les consignes d’entretien. Si une information manque, posez la question : une matière ou une taille ne se devine pas sur une photographie.\n\n## Le petit exercice à essayer\n\nPhotographiez cinq tenues que vous aimez avec vos propres vêtements. Gardez ces images à portée de main les matins pressés. La capsule devient alors un outil personnel, évolutif, fait pour être porté plutôt que parfait sur un portant."},"en":{"title":"A capsule wardrobe that actually feels like you","excerpt":"A practical way to build an easy-to-wear wardrobe around your real days, preferences and existing clothes.","body":"A useful capsule wardrobe starts with your actual week, not a universal list of essentials. Consider travel, work, quieter days and the weather. The aim is easier decisions, while keeping your personal style.\n\n## Notice what you already wear\n\nSet aside the clothes you reach for naturally. Look for shared features: a comfortable waist, a useful length or colours you enjoy combining. These observations reveal more than a shopping list.\n\n## Build outfits before buying\n\nChoose two or three base colours and one accent you love. Make three complete outfits for different parts of your week. Change one element at a time: a jacket, trousers or shoes can create a new direction without replacing everything.\n\n## Give each purchase a purpose\n\nAsk which existing clothes a new piece will work with. Check the available measurements, fit advice and care label. Do not infer fabric composition or size from a photograph.\n\n## Keep a personal outfit library\n\nPhotograph five combinations you genuinely enjoy wearing. Use them on busy mornings, and adjust your selection as your routine changes. A capsule is a working wardrobe, not a fixed rule."},"ar":{"title":"خزانة صغيرة ومنسقة تعكس ذوقك","excerpt":"خطوات عملية لتنسيق ملابس تناسب أيامك الفعلية وتمنح القطع الموجودة إمكانيات أكثر.","body":"تبدأ الخزانة العملية بنمط حياتك الحقيقي: العمل والتنقل والراحة والطقس. الهدف هو تسهيل الاختيار مع الحفاظ على ذوقك، وليس الالتزام بقائمة ثابتة من القطع.\n\n## ملاحظة ما ترتديه فعلاً\n\nضع جانباً القطع التي تختارها تلقائياً. ما الذي يجمعها؟ خصر مريح أو طول مناسب أو ألوان سهلة التنسيق؟ هذه الملاحظات تساعدك على فهم احتياجاتك.\n\n## تنسيق إطلالات كاملة\n\nاختر لونين أو ثلاثة كأساس وأضف لوناً تحبه. جهّز ثلاثة تنسيقات لأوقات مختلفة من الأسبوع، ثم بدّل قطعة واحدة لاكتشاف خيارات جديدة.\n\n## الشراء لهدف واضح\n\nقبل شراء قطعة، حدّد الملابس الموجودة التي تناسبها. راجع القياسات والمعلومات المتاحة وتعليمات العناية. لا يمكن الجزم بالخامة أو المقاس اعتماداً على الصورة.\n\n## تجربة بسيطة\n\nصوّر خمسة تنسيقات تحب ارتداءها وارجع إليها عندما يضيق الوقت. تتطور الخزانة مع يومك واحتياجاتك، ولا تحتاج إلى أن تكون مثالية."}}},{"slug":"art-abaya-moderne","title":"L’art des superpositions : du relief, sans compliquer la tenue","category":"Silhouettes","excerpt":"Jouer avec les longueurs, les volumes et les textures pour composer une silhouette lisible et agréable à porter.","body":"Superposer n’oblige pas à accumuler. Une base simple et une pièce extérieure bien choisie créent déjà du relief. L’intérêt se trouve souvent dans la façon dont un col, une manche ou un ourlet répond à une autre ligne.\n\n## Commencer par une base confortable\n\nEssayez d’abord le haut et le bas sans veste. Vérifiez que vous pouvez vous asseoir et marcher aisément. La pièce extérieure doit enrichir une tenue qui fonctionne déjà, plutôt que corriger un inconfort.\n\n## Donner un rôle à chaque longueur\n\nUn haut plus court avec un pantalon ample produit une lecture différente d’une pièce longue laissée ouverte. Regardez la silhouette dans son ensemble, puis choisissez la ligne que vous souhaitez mettre en valeur. Il n’existe pas de proportion obligatoire.\n\n## Équilibrer les volumes selon vos envies\n\nSi les manches et le pantalon sont amples, une ligne de col nette ou une ouverture verticale peut structurer l’ensemble. À l’inverse, une base sobre accueille facilement une veste plus expressive. Ce sont des pistes d’essayage, pas des règles liées à une morphologie.\n\n## Laisser dialoguer les textures\n\nUne surface lisse près d’une maille visuellement plus présente apporte du contraste. Limitez les éléments qui attirent simultanément le regard si vous recherchez un résultat calme. Pour un effet plus affirmé, rapprochez deux textures, puis gardez les accessoires simples.\n\n## Vérifier la tenue en mouvement\n\nLevez les bras, asseyez-vous, fermez la veste et essayez votre sac. Les épaisseurs doivent rester compatibles avec vos gestes et la température. Une photographie immobile ne dit pas tout du confort.\n\n## Une formule facile à réinterpréter\n\nPartez d’un pantalon que vous portez souvent, ajoutez un haut uni et essayez deux pièces extérieures de longueurs différentes. Gardez celle qui vous donne envie de bouger et de sortir : la bonne superposition reste celle que vous aurez plaisir à porter.","image":"/images/journal-superpositions.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"L’art des superpositions : du relief, sans compliquer la tenue","excerpt":"Jouer avec les longueurs, les volumes et les textures pour composer une silhouette lisible et agréable à porter.","body":"Superposer n’oblige pas à accumuler. Une base simple et une pièce extérieure bien choisie créent déjà du relief. L’intérêt se trouve souvent dans la façon dont un col, une manche ou un ourlet répond à une autre ligne.\n\n## Commencer par une base confortable\n\nEssayez d’abord le haut et le bas sans veste. Vérifiez que vous pouvez vous asseoir et marcher aisément. La pièce extérieure doit enrichir une tenue qui fonctionne déjà, plutôt que corriger un inconfort.\n\n## Donner un rôle à chaque longueur\n\nUn haut plus court avec un pantalon ample produit une lecture différente d’une pièce longue laissée ouverte. Regardez la silhouette dans son ensemble, puis choisissez la ligne que vous souhaitez mettre en valeur. Il n’existe pas de proportion obligatoire.\n\n## Équilibrer les volumes selon vos envies\n\nSi les manches et le pantalon sont amples, une ligne de col nette ou une ouverture verticale peut structurer l’ensemble. À l’inverse, une base sobre accueille facilement une veste plus expressive. Ce sont des pistes d’essayage, pas des règles liées à une morphologie.\n\n## Laisser dialoguer les textures\n\nUne surface lisse près d’une maille visuellement plus présente apporte du contraste. Limitez les éléments qui attirent simultanément le regard si vous recherchez un résultat calme. Pour un effet plus affirmé, rapprochez deux textures, puis gardez les accessoires simples.\n\n## Vérifier la tenue en mouvement\n\nLevez les bras, asseyez-vous, fermez la veste et essayez votre sac. Les épaisseurs doivent rester compatibles avec vos gestes et la température. Une photographie immobile ne dit pas tout du confort.\n\n## Une formule facile à réinterpréter\n\nPartez d’un pantalon que vous portez souvent, ajoutez un haut uni et essayez deux pièces extérieures de longueurs différentes. Gardez celle qui vous donne envie de bouger et de sortir : la bonne superposition reste celle que vous aurez plaisir à porter."},"en":{"title":"Thoughtful layering, without overcomplicating an outfit","excerpt":"Use lengths, volume and texture to create depth while keeping comfort and clarity.","body":"Layering can start with just a comfortable base and one outer piece. A collar, sleeve or hem can add interest without adding many garments.\n\n## Let the base work first\n\nTry the top and bottoms without a jacket. Sit, walk and move your arms. The outer layer should enrich an outfit that already feels good.\n\n## Explore lengths and volumes\n\nA short top with wide trousers creates a different line from a long open jacket. Neither is a universal ideal. Try both and notice the silhouette you prefer. A clean neckline or vertical opening can bring definition to generous shapes.\n\n## Combine texture deliberately\n\nA smooth surface next to a more prominent knit creates contrast. If you want a calm result, limit competing details. For a stronger effect, combine textures and keep accessories simple.\n\n## Make movement part of the fitting\n\nClose the jacket, carry your bag and sit down. Check that the layers suit both the temperature and your daily gestures. The most successful combination is one you enjoy wearing, not simply photographing."},"ar":{"title":"تنسيق الطبقات ببساطة وراحة","excerpt":"أفكار لتجربة الأطوال والأحجام والملمس دون تعقيد الإطلالة.","body":"لا يتطلب تنسيق الطبقات كثرة القطع. قد يكفي أساس مريح وسترة مناسبة لإضافة عمق من خلال الياقة أو الأكمام أو اختلاف الأطوال.\n\n## البداية من أساس مريح\n\nجرّب القطعة العلوية والبنطال من دون سترة، ثم اجلس وامشِ وارفع ذراعيك. يفترض أن تضيف الطبقة الخارجية شيئاً إلى تنسيق مريح أصلاً.\n\n## تجربة الأطوال والأحجام\n\nيختلف أثر القطعة القصيرة مع البنطال الواسع عن السترة الطويلة المفتوحة. لا توجد نسبة مثالية للجميع. جرّب ما يوافق ذوقك، واستعن بخط ياقة واضح أو فتحة عمودية إذا رغبت في تحديد الشكل.\n\n## الاهتمام بالملمس والحركة\n\nيمكن لسطح ناعم بجانب نسيج أكثر بروزاً أن يصنع تبايناً هادئاً. احمل حقيبتك وأغلق السترة وتأكد من مناسبة الطبقات لدرجة الحرارة وحركتك اليومية."}}},{"slug":"guide-tenues-priere","title":"Bien choisir une coupe : les détails qui changent le confort","category":"Bien choisir","excerpt":"Mesures, aisance, longueur et mouvement : les bons réflexes pour choisir une pièce à distance avec plus de confiance.","body":"Une coupe confortable se reconnaît dans les gestes ordinaires. Marcher, s’asseoir ou tendre les bras révèle parfois ce qu’un miroir ne montre pas. Lors d’un achat en ligne, quelques vérifications concrètes aident à se projeter sans promettre un résultat universel.\n\n## Comparer avec une pièce connue\n\nPrenez un vêtement dans lequel vous êtes à l’aise, posez-le à plat et mesurez les dimensions utiles. Comparez uniquement des mesures prises de la même façon. Un tour du corps et une largeur de vêtement à plat ne sont pas interchangeables.\n\n## Lire « taille unique » avec précision\n\nCette mention décrit une proposition de taille, pas la garantie qu’une pièce conviendra à tout le monde. Consultez la plage conseillée lorsqu’elle est renseignée, les mesures vérifiées et le type de coupe. Demandez une précision si vous hésitez.\n\n## Repérer où se trouve l’aisance\n\nSur un haut, regardez les épaules, l’ouverture des manches et la longueur. Sur un pantalon, intéressez-vous à la taille, à la hauteur de fourche et à la jambe. Un volume ample peut être agréable, mais il doit rester compatible avec vos usages.\n\n## Distinguer l’apparence et la composition\n\nUne maille qui semble épaisse ou un tissu qui paraît fluide ne permet pas de connaître sa composition exacte. Fiez-vous aux informations confirmées sur la fiche ou à l’étiquette du vêtement. Le confort thermique dépend aussi de votre environnement et des autres couches portées.\n\n## Faire un essayage utile\n\nÀ réception, essayez la pièce avec les chaussures et sous-couches prévues, en respectant les conditions d’essayage et de retour. Testez plusieurs mouvements et prenez le temps d’observer les points de tension.\n\n## La question à poser avant de commander\n\nRemplacez « est-ce que cela taille bien ? » par une question précise : quelle est la longueur, la largeur à plat, ou la mesure de taille disponible ? Une réponse factuelle aide davantage qu’une appréciation générale.","image":"/images/journal-confort.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Bien choisir une coupe : les détails qui changent le confort","excerpt":"Mesures, aisance, longueur et mouvement : les bons réflexes pour choisir une pièce à distance avec plus de confiance.","body":"Une coupe confortable se reconnaît dans les gestes ordinaires. Marcher, s’asseoir ou tendre les bras révèle parfois ce qu’un miroir ne montre pas. Lors d’un achat en ligne, quelques vérifications concrètes aident à se projeter sans promettre un résultat universel.\n\n## Comparer avec une pièce connue\n\nPrenez un vêtement dans lequel vous êtes à l’aise, posez-le à plat et mesurez les dimensions utiles. Comparez uniquement des mesures prises de la même façon. Un tour du corps et une largeur de vêtement à plat ne sont pas interchangeables.\n\n## Lire « taille unique » avec précision\n\nCette mention décrit une proposition de taille, pas la garantie qu’une pièce conviendra à tout le monde. Consultez la plage conseillée lorsqu’elle est renseignée, les mesures vérifiées et le type de coupe. Demandez une précision si vous hésitez.\n\n## Repérer où se trouve l’aisance\n\nSur un haut, regardez les épaules, l’ouverture des manches et la longueur. Sur un pantalon, intéressez-vous à la taille, à la hauteur de fourche et à la jambe. Un volume ample peut être agréable, mais il doit rester compatible avec vos usages.\n\n## Distinguer l’apparence et la composition\n\nUne maille qui semble épaisse ou un tissu qui paraît fluide ne permet pas de connaître sa composition exacte. Fiez-vous aux informations confirmées sur la fiche ou à l’étiquette du vêtement. Le confort thermique dépend aussi de votre environnement et des autres couches portées.\n\n## Faire un essayage utile\n\nÀ réception, essayez la pièce avec les chaussures et sous-couches prévues, en respectant les conditions d’essayage et de retour. Testez plusieurs mouvements et prenez le temps d’observer les points de tension.\n\n## La question à poser avant de commander\n\nRemplacez « est-ce que cela taille bien ? » par une question précise : quelle est la longueur, la largeur à plat, ou la mesure de taille disponible ? Une réponse factuelle aide davantage qu’une appréciation générale."},"en":{"title":"Choosing a fit: small details that make a difference","excerpt":"Measurements, ease and movement: practical checks for choosing clothes online with more confidence.","body":"Comfort shows itself when you walk, sit or reach. When buying online, start with a garment you know and enjoy wearing.\n\n## Compare like-for-like measurements\n\nLay your reference garment flat and measure the relevant areas. Only compare measurements taken in the same way: body circumference and a flat garment width are different things.\n\n## Read one-size information carefully\n\nOne size is not a promise of universal fit. Check any confirmed measurements, recommended range and fit advice. Ask for a specific dimension when information is missing.\n\n## Look at ease and length\n\nFor tops, consider shoulders, sleeves and length. For trousers, consider the waist, rise and leg. A generous cut should still suit your movements and daily routine.\n\n## Separate appearance from confirmed facts\n\nA photograph cannot establish fabric composition or warmth. Use the product information and care label. On arrival, try the garment with your intended layers and shoes, respecting the fitting and return conditions."},"ar":{"title":"اختيار القصة: تفاصيل تصنع الفرق في الراحة","excerpt":"القياسات وسهولة الحركة والطول: خطوات عملية عند شراء الملابس عبر الإنترنت.","body":"تظهر الراحة عند المشي والجلوس ومد الذراعين. يمكن الاستعانة بقطعة تملكها وتشعر فيها بالراحة قبل اختيار قطعة جديدة.\n\n## مقارنة القياسات بالطريقة نفسها\n\nضع القطعة على سطح مستوٍ وقس الأبعاد المهمة. لا تقارن محيط الجسم بعرض القطعة وهي مفرودة، فهما قياسان مختلفان.\n\n## فهم المقاس الواحد\n\nعبارة المقاس الواحد لا تعني ملاءمة الجميع. راجع المدى الموصى به والقياسات المؤكدة ونصائح القصة، واطلب معلومة محددة إذا كانت ناقصة.\n\n## مراعاة الحركة والخامة\n\nانتبه إلى الكتفين والأكمام والطول في القطع العلوية، وإلى الخصر وارتفاعه والساق في البناطيل. لا تكفي الصورة لتحديد تركيب الخامة أو دفئها. جرّب القطعة عند الاستلام وفق شروط التجربة والإرجاع."}}},{"slug":"mode-modeste-2026","title":"Associer les couleurs sans suivre de règles rigides","category":"Couleurs","excerpt":"Une base, une couleur d’accent et quelques essais : construire une palette personnelle devient plus simple.","body":"Associer les couleurs n’est pas un examen à réussir. Il s’agit de trouver des rapprochements qui vous plaisent et qui fonctionnent avec vos vêtements. La lumière, la texture et les proportions influencent autant le résultat que le nom d’une teinte.\n\n## Choisir l’atmosphère avant la palette\n\nSouhaitez-vous une tenue discrète, lumineuse ou plus contrastée ? Cette intention aide à choisir. Un camaïeu peut donner une impression calme ; une couleur d’accent peut devenir le point de départ d’un ensemble plus expressif.\n\n## Tester une couleur en petite proportion\n\nSi une teinte vous attire sans vous sembler facile, commencez par une seule pièce. Essayez-la avec deux bases différentes. Photographiez les associations en lumière naturelle : cela aide à comparer sans multiplier les achats.\n\n## Donner de la profondeur aux neutres\n\nDes nuances proches ne sont pas nécessairement identiques. Crème, beige et taupe peuvent dialoguer, mais leur sous-ton et leur texture modifient l’équilibre. Posez les pièces côte à côte plutôt que de vous fier aux noms affichés à l’écran.\n\n## Garder un point de repère\n\nDans une association très colorée, répéter discrètement une teinte dans une autre partie de la tenue peut créer un lien. Si vous préférez des contrastes francs, laissez-les exister : l’harmonie ne signifie pas tout assortir.\n\n## Comprendre la limite des photos\n\nL’écran, l’éclairage de la prise de vue et les réglages de l’appareil influencent la couleur perçue. Les pastilles sont des repères de sélection, pas des mesures du tissu. Vérifiez les photos associées au coloris ; une vue générale ne confirme pas une teinte particulière.\n\n## Un exercice pour trouver votre palette\n\nChoisissez une couleur que vous aimez déjà et composez trois versions : avec une base claire, une base foncée et une nuance proche. Gardez les associations dans lesquelles vous vous sentez le mieux, sans chercher une validation extérieure.","image":"/images/journal-couleurs.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Associer les couleurs sans suivre de règles rigides","excerpt":"Une base, une couleur d’accent et quelques essais : construire une palette personnelle devient plus simple.","body":"Associer les couleurs n’est pas un examen à réussir. Il s’agit de trouver des rapprochements qui vous plaisent et qui fonctionnent avec vos vêtements. La lumière, la texture et les proportions influencent autant le résultat que le nom d’une teinte.\n\n## Choisir l’atmosphère avant la palette\n\nSouhaitez-vous une tenue discrète, lumineuse ou plus contrastée ? Cette intention aide à choisir. Un camaïeu peut donner une impression calme ; une couleur d’accent peut devenir le point de départ d’un ensemble plus expressif.\n\n## Tester une couleur en petite proportion\n\nSi une teinte vous attire sans vous sembler facile, commencez par une seule pièce. Essayez-la avec deux bases différentes. Photographiez les associations en lumière naturelle : cela aide à comparer sans multiplier les achats.\n\n## Donner de la profondeur aux neutres\n\nDes nuances proches ne sont pas nécessairement identiques. Crème, beige et taupe peuvent dialoguer, mais leur sous-ton et leur texture modifient l’équilibre. Posez les pièces côte à côte plutôt que de vous fier aux noms affichés à l’écran.\n\n## Garder un point de repère\n\nDans une association très colorée, répéter discrètement une teinte dans une autre partie de la tenue peut créer un lien. Si vous préférez des contrastes francs, laissez-les exister : l’harmonie ne signifie pas tout assortir.\n\n## Comprendre la limite des photos\n\nL’écran, l’éclairage de la prise de vue et les réglages de l’appareil influencent la couleur perçue. Les pastilles sont des repères de sélection, pas des mesures du tissu. Vérifiez les photos associées au coloris ; une vue générale ne confirme pas une teinte particulière.\n\n## Un exercice pour trouver votre palette\n\nChoisissez une couleur que vous aimez déjà et composez trois versions : avec une base claire, une base foncée et une nuance proche. Gardez les associations dans lesquelles vous vous sentez le mieux, sans chercher une validation extérieure."},"en":{"title":"Combining colours without rigid rules","excerpt":"Build a personal palette through a base, an accent and a few useful experiments.","body":"Colour combinations are a matter of preference, not a test. Light, texture and proportion all change the way an outfit feels.\n\n## Start with an intention\n\nDo you want a quiet, bright or contrasting outfit? Related shades can feel calm, while an accent creates a focal point. Try one new colour with two bases you already own.\n\n## Give neutrals some depth\n\nCream, beige and taupe are not interchangeable. Place garments side by side to compare undertones and textures instead of relying only on colour names.\n\n## Use photographs thoughtfully\n\nScreens and lighting affect colour perception. Swatches are selection aids, not fabric measurements. Check photographs actually assigned to your chosen colour; a general view does not confirm a specific shade.\n\n## Try three combinations\n\nChoose a colour you already enjoy. Wear it with a light base, a dark base and a neighbouring shade. Keep the versions that feel right to you."},"ar":{"title":"تنسيق الألوان بعيداً عن القواعد الجامدة","excerpt":"لون أساسي ولمسة مميزة وتجارب بسيطة لبناء لوحة ألوان شخصية.","body":"تنسيق الألوان مسألة ذوق وتجربة. تؤثر الإضاءة والخامة ونسبة كل لون في النتيجة النهائية.\n\n## تحديد الإحساس المطلوب\n\nهل ترغب في تنسيق هادئ أم مشرق أم واضح التباين؟ جرّب لوناً واحداً جديداً مع أساسين موجودين في خزانتك.\n\n## مقارنة الدرجات المتقاربة\n\nالكريمي والبيج والتاوب ليست درجات متطابقة. ضع القطع جنباً إلى جنب لملاحظة اختلاف الدرجة والملمس، بدلاً من الاكتفاء بالاسم.\n\n## الانتباه إلى الصور\n\nتؤثر الشاشة وإضاءة التصوير في اللون الظاهر. دوائر الألوان أدوات للاختيار وليست قياسات للخامة. راجع الصور المرتبطة باللون المحدد؛ فالصورة العامة لا تؤكد درجة بعينها.\n\n## تجربة ثلاث مجموعات\n\nنسّق لوناً تحبه مع أساس فاتح وآخر داكن ودرجة قريبة. احتفظ بما يناسب ذوقك وراحتك."}}},{"slug":"entretien-hijabs-soie","title":"Laver, sécher, ranger : les réflexes d’une garde-robe soignée","category":"Entretien","excerpt":"Des gestes mesurés et une attention à l’étiquette, plutôt qu’une méthode unique appliquée à tous les vêtements.","body":"Prendre soin d’un vêtement commence avant le lavage. Observer une petite tache, aérer une pièce lorsque cela convient et ranger sans comprimer sont déjà des gestes utiles. L’objectif est de respecter le vêtement, sans lui appliquer une recette universelle.\n\n## L’étiquette reste le premier repère\n\nVérifiez les symboles et les instructions du fabricant. Une maille, une doublure et un accessoire peuvent imposer des précautions différentes, même si l’ensemble semble simple. Si la consigne est absente ou ambiguë, demandez conseil avant d’utiliser un procédé agressif.\n\n## Préparer le lavage\n\nVidez les poches, vérifiez les fermetures et séparez les textiles selon les indications pertinentes. Une couleur foncée ou un tissu visuellement délicat n’indique pas à lui seul le bon programme. Utilisez la température et le traitement autorisés pour la pièce concernée.\n\n## Traiter une tache avec prudence\n\nÉvitez de frotter vigoureusement ou d’appliquer un produit au hasard. Un essai sur une zone discrète ne remplace pas les consignes, mais peut aider à repérer une réaction indésirable lorsque le traitement est autorisé. Pour une pièce délicate ou une tache difficile, un professionnel peut être préférable.\n\n## Respecter la forme pendant le séchage\n\nLe sèche-linge, le séchage suspendu ou à plat ne conviennent pas indistinctement à toutes les pièces. Suivez l’étiquette et disposez le vêtement sans déformer les zones fragiles. La chaleur et l’essorage doivent eux aussi correspondre aux instructions.\n\n## Ranger pour retrouver facilement\n\nLaissez suffisamment d’espace entre les pièces et choisissez le pliage ou le cintre adapté à leur tenue. Rangez des vêtements propres et complètement secs. Réparez un bouton desserré avant qu’il ne se perde : ce petit geste évite parfois une mise de côté durable.\n\n## Un entretien ajusté à la pièce\n\nGardez une photo des étiquettes difficiles à lire. Lors d’un prochain achat, consultez les informations d’entretien disponibles et demandez ce qui manque. Connaître les contraintes d’une pièce aide à choisir un vêtement compatible avec votre quotidien.","image":"/images/journal-entretien.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Laver, sécher, ranger : les réflexes d’une garde-robe soignée","excerpt":"Des gestes mesurés et une attention à l’étiquette, plutôt qu’une méthode unique appliquée à tous les vêtements.","body":"Prendre soin d’un vêtement commence avant le lavage. Observer une petite tache, aérer une pièce lorsque cela convient et ranger sans comprimer sont déjà des gestes utiles. L’objectif est de respecter le vêtement, sans lui appliquer une recette universelle.\n\n## L’étiquette reste le premier repère\n\nVérifiez les symboles et les instructions du fabricant. Une maille, une doublure et un accessoire peuvent imposer des précautions différentes, même si l’ensemble semble simple. Si la consigne est absente ou ambiguë, demandez conseil avant d’utiliser un procédé agressif.\n\n## Préparer le lavage\n\nVidez les poches, vérifiez les fermetures et séparez les textiles selon les indications pertinentes. Une couleur foncée ou un tissu visuellement délicat n’indique pas à lui seul le bon programme. Utilisez la température et le traitement autorisés pour la pièce concernée.\n\n## Traiter une tache avec prudence\n\nÉvitez de frotter vigoureusement ou d’appliquer un produit au hasard. Un essai sur une zone discrète ne remplace pas les consignes, mais peut aider à repérer une réaction indésirable lorsque le traitement est autorisé. Pour une pièce délicate ou une tache difficile, un professionnel peut être préférable.\n\n## Respecter la forme pendant le séchage\n\nLe sèche-linge, le séchage suspendu ou à plat ne conviennent pas indistinctement à toutes les pièces. Suivez l’étiquette et disposez le vêtement sans déformer les zones fragiles. La chaleur et l’essorage doivent eux aussi correspondre aux instructions.\n\n## Ranger pour retrouver facilement\n\nLaissez suffisamment d’espace entre les pièces et choisissez le pliage ou le cintre adapté à leur tenue. Rangez des vêtements propres et complètement secs. Réparez un bouton desserré avant qu’il ne se perde : ce petit geste évite parfois une mise de côté durable.\n\n## Un entretien ajusté à la pièce\n\nGardez une photo des étiquettes difficiles à lire. Lors d’un prochain achat, consultez les informations d’entretien disponibles et demandez ce qui manque. Connaître les contraintes d’une pièce aide à choisir un vêtement compatible avec votre quotidien."},"en":{"title":"Wash, dry, store: thoughtful care for everyday clothes","excerpt":"Start with the care label and adapt your routine to the garment, rather than following one universal method.","body":"Garment care begins before washing. Look at the item, check the care label and avoid treating every fabric in the same way.\n\n## Read the actual instructions\n\nLinings, trims and different materials can require different precautions. Follow the manufacturer’s symbols. If information is missing, ask before using an aggressive treatment.\n\n## Prepare and treat carefully\n\nEmpty pockets and check fastenings. Sort clothes according to the relevant instructions, not appearance alone. Do not scrub a stain vigorously or apply an unfamiliar product at random. A professional may be the better choice for a delicate garment or difficult mark.\n\n## Dry without distorting\n\nTumble drying, hanging and flat drying are not universally suitable. Use the method allowed for that garment and avoid stretching vulnerable areas. Heat and spin settings should also follow the label.\n\n## Store with room to breathe\n\nPut away clean, completely dry garments using suitable hangers or folds. Repair loose buttons promptly. Keep a photograph of hard-to-read labels and consider care requirements before your next purchase."},"ar":{"title":"الغسل والتجفيف والترتيب: عناية مدروسة بالملابس","excerpt":"ابدأ ببطاقة العناية وكيّف خطواتك مع كل قطعة بدلاً من اتباع طريقة واحدة للجميع.","body":"تبدأ العناية بملاحظة القطعة وقراءة تعليماتها. قد تفرض البطانة والزينة والخامات المختلفة احتياطات خاصة.\n\n## بطاقة العناية أولاً\n\nاتبع رموز وتعليمات المصنّع. عند غياب المعلومة، اسأل قبل استخدام معالجة قوية أو حرارة غير مناسبة.\n\n## التحضير ومعالجة البقع\n\nأفرغ الجيوب وافحص السحابات والأزرار. لا تفرك البقعة بقوة أو تستخدم منتجاً عشوائياً. قد تكون الاستعانة بمتخصص أنسب للقطع الحساسة أو البقع الصعبة.\n\n## الحفاظ على الشكل\n\nلا يناسب التجفيف الآلي أو التعليق أو التجفيف المسطح جميع القطع. التزم بالطريقة والحرارة المسموح بهما، وتجنب شد المناطق الضعيفة.\n\n## ترتيب الملابس الجافة\n\nاختر علاقة أو طريقة طي مناسبة، واترك مساحة كافية. أصلح الزر المرتخي واحتفظ بصورة للتعليمات التي يصعب قراءتها."}}},{"slug":"idees-tenues-aid","title":"Du quotidien à une occasion : faire évoluer une tenue en trois gestes","category":"Inspirations","excerpt":"Une même base, plusieurs ambiances : changer le rythme d’un ensemble avec une pièce extérieure, des chaussures et quelques détails.","body":"Une occasion ne demande pas forcément une nouvelle tenue complète. Une base que vous connaissez bien peut prendre une autre direction avec quelques changements choisis. Le confort déjà éprouvé devient un allié, surtout lorsque la journée se prolonge.\n\n## Premier geste : changer la pièce extérieure\n\nUne veste plus structurée, une pièce longue ouverte ou une superposition plus légère modifie la ligne d’ensemble. Essayez la tenue fermée et ouverte. Choisissez selon le lieu et la température plutôt que selon une idée abstraite de ce qui ferait « habillé ».\n\n## Deuxième geste : adapter les chaussures\n\nLes chaussures changent la posture visuelle autant que la façon de se déplacer. Pensez à la durée debout, au trajet et au type de sol. Il n’est pas nécessaire de choisir des talons pour composer une tenue soignée : une paire confortable et adaptée à l’ensemble peut très bien remplir ce rôle.\n\n## Troisième geste : sélectionner un détail\n\nUn sac, une ceinture si la coupe le permet, ou un accessoire peut devenir le point d’attention. Évitez d’ajouter des éléments uniquement parce que l’occasion semble le demander. Un détail que vous aimez suffit souvent à personnaliser une base sobre.\n\n## Prévoir les aspects pratiques\n\nVérifiez les poches, la facilité à porter votre sac et les variations de température. Si vous transportez une seconde paire de chaussures ou une couche supplémentaire, préparez-les avec la tenue. Une bonne organisation évite les changements précipités.\n\n## Faire un essai avant le jour prévu\n\nEssayez l’ensemble quelques minutes en mouvement. Une longueur qui fonctionne avec une paire de chaussures peut être moins pratique avec une autre. Regardez aussi le rendu à la lumière du jour, sans chercher une image parfaite.\n\n## Garder votre propre définition de l’élégance\n\nUne tenue réussie correspond au moment, mais aussi à la personne qui la porte. Réutiliser des pièces et les associer autrement est une démarche créative : vous construisez davantage de possibilités à partir de ce que vous aimez déjà.","image":"/images/journal-occasions.webp","author":"La rédaction Hanna & Nour","read_minutes":2,"translations":{"fr":{"title":"Du quotidien à une occasion : faire évoluer une tenue en trois gestes","excerpt":"Une même base, plusieurs ambiances : changer le rythme d’un ensemble avec une pièce extérieure, des chaussures et quelques détails.","body":"Une occasion ne demande pas forcément une nouvelle tenue complète. Une base que vous connaissez bien peut prendre une autre direction avec quelques changements choisis. Le confort déjà éprouvé devient un allié, surtout lorsque la journée se prolonge.\n\n## Premier geste : changer la pièce extérieure\n\nUne veste plus structurée, une pièce longue ouverte ou une superposition plus légère modifie la ligne d’ensemble. Essayez la tenue fermée et ouverte. Choisissez selon le lieu et la température plutôt que selon une idée abstraite de ce qui ferait « habillé ».\n\n## Deuxième geste : adapter les chaussures\n\nLes chaussures changent la posture visuelle autant que la façon de se déplacer. Pensez à la durée debout, au trajet et au type de sol. Il n’est pas nécessaire de choisir des talons pour composer une tenue soignée : une paire confortable et adaptée à l’ensemble peut très bien remplir ce rôle.\n\n## Troisième geste : sélectionner un détail\n\nUn sac, une ceinture si la coupe le permet, ou un accessoire peut devenir le point d’attention. Évitez d’ajouter des éléments uniquement parce que l’occasion semble le demander. Un détail que vous aimez suffit souvent à personnaliser une base sobre.\n\n## Prévoir les aspects pratiques\n\nVérifiez les poches, la facilité à porter votre sac et les variations de température. Si vous transportez une seconde paire de chaussures ou une couche supplémentaire, préparez-les avec la tenue. Une bonne organisation évite les changements précipités.\n\n## Faire un essai avant le jour prévu\n\nEssayez l’ensemble quelques minutes en mouvement. Une longueur qui fonctionne avec une paire de chaussures peut être moins pratique avec une autre. Regardez aussi le rendu à la lumière du jour, sans chercher une image parfaite.\n\n## Garder votre propre définition de l’élégance\n\nUne tenue réussie correspond au moment, mais aussi à la personne qui la porte. Réutiliser des pièces et les associer autrement est une démarche créative : vous construisez davantage de possibilités à partir de ce que vous aimez déjà."},"en":{"title":"Everyday to occasion: three thoughtful outfit changes","excerpt":"Give a familiar outfit a different mood through an outer layer, shoes and one personal detail.","body":"An occasion does not always need an entirely new outfit. Start with a base you already feel comfortable wearing and make a few deliberate changes.\n\n## Change the outer layer\n\nA structured jacket, a long open piece or a lighter layer changes the overall line. Try it open and closed, and consider the setting and temperature.\n\n## Choose shoes for the whole event\n\nThink about travel, time spent standing and the surface underfoot. Heels are not a requirement for a polished outfit. Comfortable shoes that work with the clothes can be just as considered.\n\n## Select one personal detail\n\nA bag, a suitable belt or an accessory can create a focal point. You do not need to add things simply because the occasion feels formal.\n\n## Rehearse the practical details\n\nTry the complete outfit in movement, including your bag and shoes. Check lengths and prepare an extra layer if needed. Reinterpreting familiar pieces is a creative way to discover more possibilities in the clothes you already enjoy."},"ar":{"title":"من اليوم العادي إلى المناسبة بثلاث لمسات","excerpt":"تغيير طابع تنسيق مألوف من خلال طبقة خارجية وحذاء وتفصيل شخصي.","body":"لا تتطلب المناسبة شراء إطلالة كاملة. ابدأ بملابس تعرف راحتها وأضف تغييرات محددة تناسب المكان والوقت.\n\n## تغيير الطبقة الخارجية\n\nتغيّر سترة محددة القصة أو قطعة طويلة مفتوحة خط الإطلالة. جرّبها مفتوحة ومغلقة وراعِ الطقس.\n\n## اختيار حذاء مناسب\n\nفكّر في التنقل ومدة الوقوف والأرضية. لا يشترط الكعب للحصول على تنسيق أنيق؛ فالحذاء المريح المتناسق قد يؤدي الدور نفسه.\n\n## إضافة تفصيل تحبه\n\nقد تصنع حقيبة أو حزام مناسب للقصة أو إكسسوار نقطة اهتمام. لا تضف تفاصيل لمجرد أن المناسبة تبدو رسمية.\n\n## تجربة التنسيق كاملاً\n\nامشِ واجلس واحمل حقيبتك وتحقق من الأطوال. إن إعادة تنسيق القطع المألوفة تمنح خزانتك خيارات جديدة وتحافظ على أسلوبك الشخصي."}}}]'::jsonb) as x(slug text,title text,category text,excerpt text,body text,image text,author text,read_minutes integer,translations jsonb))
update public.blog_posts p set title=e.title,category=e.category,excerpt=e.excerpt,body=e.body,image=e.image,author=e.author,read_minutes=e.read_minutes,translations=e.translations,updated_at=now()
from editorial e where p.slug=e.slug and p.updated_at is not distinct from (select (b.snapshot->>'updated_at')::timestamptz from public.blog_editorial_backups b where b.post_id=p.id and b.revision='journal-refresh-v1');
commit;
